CREATE TABLE IF NOT EXISTS public.medication_reconciliation_workflows ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, patient_id UUID NOT NULL REFERENCES public.patients(id), admission_type TEXT NOT NULL DEFAULT 'inpatient' CHECK (admission_type IN ('inpatient','emergency','elective','transfer')), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','doctor_review','pharmacist_review','nurse_reconcile','completed','cancelled','failed')), current_step INTEGER NOT NULL DEFAULT 1, initiated_by UUID NOT NULL REFERENCES public.profiles(id), home_medications JSONB NOT NULL DEFAULT '[]', active_orders JSONB NOT NULL DEFAULT '[]', reconciled_list JSONB DEFAULT NULL, discrepancies JSONB NOT NULL DEFAULT '[]', interactions_found JSONB NOT NULL DEFAULT '[]', doctor_reviewed_by UUID REFERENCES public.profiles(id), doctor_reviewed_at TIMESTAMPTZ, pharmacist_reviewed_by UUID REFERENCES public.profiles(id), pharmacist_reviewed_at TIMESTAMPTZ, nurse_reconciled_by UUID REFERENCES public.profiles(id), nurse_reconciled_at TIMESTAMPTZ, notes TEXT, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() ); CREATE INDEX IF NOT EXISTS med_recon_hospital_idx ON public.medication_reconciliation_workflows(hospital_id); CREATE INDEX IF NOT EXISTS med_recon_patient_idx ON public.medication_reconciliation_workflows(patient_id); CREATE INDEX IF NOT EXISTS med_recon_status_idx ON public.medication_reconciliation_workflows(status) WHERE status NOT IN ('completed','cancelled'); CREATE OR REPLACE FUNCTION public.update_med_recon_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $fn$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $fn$; DROP TRIGGER IF EXISTS med_recon_updated_at_trigger ON public.medication_reconciliation_workflows; CREATE TRIGGER med_recon_updated_at_trigger BEFORE UPDATE ON public.medication_reconciliation_workflows FOR EACH ROW EXECUTE FUNCTION public.update_med_recon_updated_at(); CREATE TABLE IF NOT EXISTS public.medication_reconciliation_audit ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workflow_id UUID NOT NULL REFERENCES public.medication_reconciliation_workflows(id) ON DELETE CASCADE, hospital_id UUID NOT NULL REFERENCES public.hospitals(id), actor_id UUID NOT NULL REFERENCES public.profiles(id), actor_role TEXT NOT NULL, action TEXT NOT NULL CHECK (action IN ('initiate','doctor_review','pharmacist_review','nurse_reconcile','override','complete','cancel')), from_status TEXT, to_status TEXT, discrepancies_resolved INTEGER DEFAULT 0, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() ); ALTER TABLE public.medication_reconciliation_audit ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "med_recon_audit_hospital_read" ON medication_reconciliation_audit; CREATE POLICY "med_recon_audit_hospital_read" ON public.medication_reconciliation_audit FOR SELECT USING (public.user_belongs_to_hospital(auth.uid(), hospital_id)); CREATE INDEX IF NOT EXISTS med_recon_audit_workflow_idx ON public.medication_reconciliation_audit(workflow_id); ALTER TABLE public.medication_reconciliation_workflows ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "med_recon_hospital_read" ON medication_reconciliation_workflows; CREATE POLICY "med_recon_hospital_read" ON public.medication_reconciliation_workflows FOR SELECT USING (public.user_belongs_to_hospital(auth.uid(), hospital_id)); DROP POLICY IF EXISTS "med_recon_doctor_initiate" ON medication_reconciliation_workflows; CREATE POLICY "med_recon_doctor_initiate" ON public.medication_reconciliation_workflows FOR INSERT WITH CHECK ( public.user_belongs_to_hospital(auth.uid(), hospital_id) AND EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('doctor','admin','nurse') AND ur.hospital_id = hospital_id ) ); DROP POLICY IF EXISTS "med_recon_staff_update" ON medication_reconciliation_workflows; CREATE POLICY "med_recon_staff_update" ON public.medication_reconciliation_workflows FOR UPDATE USING ( public.user_belongs_to_hospital(auth.uid(), hospital_id) AND EXISTS ( SELECT 1 FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.role IN ('doctor','pharmacist','nurse','admin') AND ur.hospital_id = hospital_id ) );